package com.deepanshuraj.opspilot.agent; import com.deepanshuraj.opspilot.rag.*; import com.deepanshuraj.opspilot.tools.OpsTools; import java.util.*; import java.util.regex.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class AgentService {private static final Pattern ID=Pattern.compile("ORD-\\d+",Pattern.CASE_INSENSITIVE);private final OpsTools tools;private final RagRetriever rag;private final LlmClient llm;private final ConversationMemory memory;@Value("${opspilot.rag.top-k:4}")int topK;public AgentService(OpsTools t,RagRetriever r,LlmClient l,ConversationMemory m){tools=t;rag=r;llm=l;memory=m;}
public AgentResult answer(String session,String q){long start=System.currentTimeMillis();List<AgentStep>s=new ArrayList<>();StringBuilder obs=new StringBuilder();Matcher m=ID.matcher(q);String id=m.find()?m.group().toUpperCase():null;s.add(AgentStep.thought(id==null?"no order id detected.":"detected "+id+"."));if(id!=null){act(s,obs,"lookupOrder",tools.lookupOrder(id));act(s,obs,"getWorkflowStatus",tools.getWorkflowStatus(id));String l=q.toLowerCase();if(any(l,"retry","re-run","rerun","fix","resolve","unstick","re-queue","requeue"))act(s,obs,"retryStuckWorkflow",tools.retryStuckWorkflow(id));if(any(l,"ticket","raise","escalate","log a"))act(s,obs,"raiseTicket",tools.raiseTicket(id,"Assistant-raised: "+q.substring(0,Math.min(180,q.length()))));}else if(any(q.toLowerCase(),"incident","stuck order","failing","what is broken","what's broken","outage"))act(s,obs,"listRecentIncidents",tools.listRecentIncidents());List<RagRetriever.Scored> hits=rag.search(q,topK);if(!hits.isEmpty()){String x=hits.stream().map(h->"["+h.chunk().source()+"] "+h.chunk().text()).collect(java.util.stream.Collectors.joining("\n"));act(s,obs,"searchKnowledgeBase",x);}String context=hits.stream().map(h->"["+h.chunk().source()+"] "+h.chunk().text()).collect(java.util.stream.Collectors.joining("\n"));String prompt="QUESTION: "+q+"\n\nOBSERVATIONS:\n"+obs+"\nRETRIEVED CONTEXT:\n"+context+"\nCONVERSATION:\n"+String.join("\n",memory.history(session));String a=llm.complete("You are OpsPilot, an operations assistant.",prompt);memory.add(session,"user",q);memory.add(session,"assistant",a);return new AgentResult(session,q,s,a,hits.stream().map(h->h.chunk().source()).distinct().toList(),System.currentTimeMillis()-start,llm.provider());}private void act(List<AgentStep>s,StringBuilder o,String n,String r){s.add(AgentStep.action(n,"calling "+n));s.add(AgentStep.observation(n,r));o.append("- ").append(r.replace('\n',' ')).append('\n');}private boolean any(String s,String...n){return Arrays.stream(n).anyMatch(s::contains);}}
